import * as cli from "std/cli";
import * as convert from "std/convert";
import * as fs from "std/fs";
import * as io from "std/io";
import * as path from "std/path";
import * as text from "std/text";

import * as messages from "local/marimay-notes/messages";
import * as notes from "local/marimay-notes/notes";

fn fail(message: string): int {
  const _ = io.eprintln($"marimay-notes: {message}");
  return 1;
}

fn commandParser(): cli.Parser {
  return match cli.newParser(
    "marimay-notes",
    "Локальная база заметок в JSON.",
    [
      cli.flagOption("help", Some("h"), false, false, "Показать справку."),
      cli.requiredValueOption(
        "db",
        Some("d"),
        "ПУТЬ",
        false,
        false,
        "Путь к базе; по умолчанию notes.json.",
      ),
      cli.requiredValueOption(
        "tag",
        Some("t"),
        "ТЕГ",
        false,
        true,
        "Добавить тег к заметке; параметр можно повторять.",
      ),
    ],
    [
      cli.positional(
        "command",
        false,
        false,
        "add — добавить; list — список; show — показать; remove — удалить",
      ),
      cli.positional("argument", false, true, "аргумент команды"),
    ],
    cli.defaultLimits(),
  ) {
    Ok(parser) => parser,
    Err(error) => panic("Внутренняя ошибка описания команд"),
  };
}

fn firstOption(parsed: cli.Parsed, name: string): Option<string> {
  const values = cli.occurrences(parsed, name);
  if values.length() == 0 {
    return None;
  }
  return values[0];
}

fn optionValueOr(parsed: cli.Parsed, name: string, fallback: string): string {
  return match firstOption(parsed, name) {
    Some(value) => value,
    None => fallback,
  };
}

fn tags(parsed: cli.Parsed): Result<[]string, string> {
  let result: []string = [];
  for occurrence in cli.occurrences(parsed, "tag") {
    if const value = occurrence {
      result.push(value).mapError(messages.arrayGrowthError)?;
    }
  }
  return Ok(result);
}

fn databasePath(parsed: cli.Parsed): Result<path.Path, path.Error> {
  return path.fromString(optionValueOr(parsed, "db", "notes.json"));
}

fn loadDatabase(filePath: path.Path): Option<notes.Database> {
  return match fs.readBytes(filePath, 1048576) {
    Ok(contents) => match notes.decode(contents) {
      Ok(database) => Some(database),
      Err(error) => {
        const _ = fail($"Некорректная база заметок: {error}");
        None
      },
    },
    Err(error) => match error {
      fs.NotFound => Some(notes.empty()),
      _ => {
        const _ = fail(messages.fileError(error));
        None
      },
    },
  };
}

fn saveDatabase(filePath: path.Path, database: notes.Database): bool {
  const encoded = match notes.encode(database) {
    Ok(value) => value,
    Err(error) => {
      const _ = fail($"Не удалось преобразовать базу в JSON: {messages.jsonError(error)}");
      return false;
    },
  };
  return match fs.writeBytes(filePath, encoded) {
    Ok(_) => true,
    Err(error) => {
      const _ = fail(messages.fileError(error));
      false
    },
  };
}

fn printHelp(): int {
  const lines = [
    "marimay-notes — локальная база заметок",
    "",
    "Использование: marimay-notes [параметры] КОМАНДА [аргумент]",
    "",
    "Команды:",
    "  add ТЕКСТ       Добавить заметку; текст с пробелами заключайте в кавычки",
    "  list            Показать все заметки",
    "  show ID         Показать заметку по её номеру",
    "  remove ID       Удалить заметку по её номеру",
    "",
    "Параметры:",
    "  -h, --help      Показать эту справку",
    "  -d, --db ПУТЬ   Файл базы (по умолчанию: notes.json)",
    "  -t, --tag ТЕГ   Тег новой заметки; можно указать несколько раз",
    "",
    "Примеры:",
    "  marimay-notes add \"Купить чай\" --tag дом --tag покупки",
    "  marimay-notes list",
    "  marimay-notes show 1",
    "  marimay-notes --db работа.json add \"Проверить изменения\" --tag работа",
    "",
    "База создаётся при первом добавлении. Родительский каталог должен существовать.",
    "Текст и теги поддерживают русский язык и Unicode. Размер базы — до 1 МиБ.",
    "Не запускайте два процесса записи в одну базу одновременно.",
    "При запуске через mmay передавайте команды приложения после --.",
  ];
  for line in lines {
    match io.println(line) {
      Ok(_) => {},
      Err(error) => {
        return fail(messages.ioError(error));
      },
    };
  }
  return 0;
}

fn formatNote(note: notes.Note): string {
  if note.tags.length() == 0 {
    return $"#{note.id} {note.text}";
  }
  const joined = match text.join(note.tags, ", ", 1048576) {
    Ok(value) => value,
    Err(_) => "<список тегов слишком длинный>",
  };
  return $"#{note.id} {note.text} [{joined}]";
}

fn printNote(note: notes.Note): Result<void, io.Error> {
  return io.println(formatNote(note));
}

fn parseId(value: string): Option<int> {
  return match convert.parseInt(value) {
    Ok(id) => {
      if id > 0 {
        return Some(id);
      }
      None
    },
    Err(_) => None,
  };
}

fn addNote(
  parsed: cli.Parsed,
  filePath: path.Path,
  database: notes.Database,
  arguments: []string,
): int {
  if arguments.length() != 1 {
    return fail("Использование: marimay-notes add ТЕКСТ [--tag ТЕГ]...");
  }
  const selectedTags = match tags(parsed) {
    Ok(value) => value,
    Err(error) => {
      return fail(error);
    },
  };
  const added = match notes.add(database, arguments[0], selectedTags) {
    Ok(value) => value,
    Err(error) => {
      return fail(error);
    },
  };
  if !saveDatabase(filePath, added.database) {
    return 1;
  }
  return match io.println($"Добавлена заметка №{added.note.id}.") {
    Ok(_) => 0,
    Err(error) => fail(messages.ioError(error)),
  };
}

fn listNotes(database: notes.Database, arguments: []string): int {
  if arguments.length() != 0 {
    return fail("Использование: marimay-notes list");
  }
  if database.notes.length() == 0 {
    return match io.println("Заметок пока нет.") {
      Ok(_) => 0,
      Err(error) => fail(messages.ioError(error)),
    };
  }
  for note in database.notes {
    match printNote(note) {
      Ok(_) => {},
      Err(error) => {
        return fail(messages.ioError(error));
      },
    };
  }
  return 0;
}

fn showNote(database: notes.Database, arguments: []string): int {
  if arguments.length() != 1 {
    return fail("Использование: marimay-notes show ID");
  }
  const id = match parseId(arguments[0]) {
    Some(value) => value,
    None => {
      return fail("ID должен быть положительным целым числом");
    },
  };
  return match database.find(id) {
    Some(note) => match printNote(note) {
      Ok(_) => 0,
      Err(error) => fail(messages.ioError(error)),
    },
    None => fail($"Заметка №{id} не найдена"),
  };
}

fn removeNote(database: notes.Database, filePath: path.Path, arguments: []string): int {
  if arguments.length() != 1 {
    return fail("Использование: marimay-notes remove ID");
  }
  const id = match parseId(arguments[0]) {
    Some(value) => value,
    None => {
      return fail("ID должен быть положительным целым числом");
    },
  };
  if !database.remove(id) {
    return fail($"Заметка №{id} не найдена");
  }
  if !saveDatabase(filePath, database) {
    return 1;
  }
  return match io.println($"Удалена заметка №{id}.") {
    Ok(_) => 0,
    Err(error) => fail(messages.ioError(error)),
  };
}

fn run(parsed: cli.Parsed): int {
  const commands = cli.positionalValues(parsed, "command");
  if cli.count(parsed, "help") != 0 || commands.length() == 0 {
    return printHelp();
  }
  const filePath = match databasePath(parsed) {
    Ok(value) => value,
    Err(_) => {
      return fail("Некорректный путь к базе заметок");
    },
  };
  const database = match loadDatabase(filePath) {
    Some(value) => value,
    None => {
      return 1;
    },
  };
  const command = commands[0];
  const arguments = cli.positionalValues(parsed, "argument");
  if command == "add" {
    return addNote(parsed, filePath, database, arguments);
  }
  if command == "list" {
    return listNotes(database, arguments);
  }
  if command == "show" {
    return showNote(database, arguments);
  }
  if command == "remove" {
    return removeNote(database, filePath, arguments);
  }
  return fail($"Неизвестная команда «{command}». Справка: --help");
}

fn main(arguments: []string): int {
  const parser = commandParser();
  const status = match cli.parse(parser, arguments) {
    Ok(parsed) => run(parsed),
    Err(error) => {
      const _ = fail(messages.usageError(error));
      cli.usageExitStatus()
    },
  };
  if status != 0 {
    return status;
  }
  return match io.flushStdout() {
    Ok(_) => 0,
    Err(error) => fail(messages.ioError(error)),
  };
}

