import * as bytes from "std/bytes";
import * as cli from "std/cli";
import * as fs from "std/fs";
import * as io from "std/io";

import * as messages from "local/marimay-notes/messages";
import * as notes from "local/marimay-notes/notes";

@test
fn databaseErrorsAreRussian(): void {
  const emptyText = notes.add(notes.empty(), " \t", []);
  expect.equal(
    match emptyText {
      Err(message) => message,
      Ok(_) => "",
    },
    "Текст заметки не должен быть пустым",
  );
  expect.equal(
    match notes.decode(bytes.encodeUtf8("{}")) {
      Err(message) => message,
      Ok(_) => "",
    },
    "Отсутствует обязательное поле «version»: байт 2; путь: $[\"version\"]",
  );
  expect.equal(
    match notes.decode(bytes.encodeUtf8("{\"version\":1,\"nextId\":1,\"notes\":null}")) {
      Err(message) => message,
      Ok(_) => "",
    },
    "Ожидается массив JSON: байт 32; путь: $[\"notes\"]",
  );
}

@test
fn commandAndSystemErrorsAreRussian(): void {
  expect.equal(
    messages.usageError(cli.UsageError.MissingOptionValue { name: "db", index: 0 }),
    "После --db нужно указать значение",
  );
  expect.equal(
    messages.usageError(cli.UsageError.UnknownOption { argument: "--нет", index: 0 }),
    "Неизвестный параметр «--нет». Справка: --help",
  );
  expect.equal(messages.fileError(fs.Error.NotFound), "Файл или каталог не найден");
  expect.equal(messages.ioError(io.Error.WriteFailed), "Не удалось вывести сообщение");
}

@test
fn russianNotesRoundTripWithoutChangingFormat(): void {
  const added = match notes.add(notes.empty(), "Купить чай ☕", ["дом", "покупки"]) {
    Ok(value) => value,
    Err(error) => panic(error),
  };
  const data = match notes.encode(added.database) {
    Ok(value) => value,
    Err(error) => panic(messages.jsonError(error)),
  };
  const restored = match notes.decode(data) {
    Ok(value) => value,
    Err(error) => panic(error),
  };
  expect.equal(restored.notes[0].text, "Купить чай ☕");
  expect.equal(restored.notes[0].tags[1], "покупки");
  expect.equal(restored.nextId, 2);
}

